_⚠️ Potential issue_ | _🟠 Major_

**Preserve story-level `render` precedence when identifier resolution fails.**

When a story has `render` but it cannot be resolved (Lines 139-140), `getRenderPath` returns `undefined`, which is indistinguishable from “no render property.” Then Line 155 can incorrectly fall back to `meta.render`, producing a snippet for the wrong renderer.


<details>
<summary>💡 Proposed fix (introduce tri-state render resolution)</summary>

```diff
+  type RenderResolution =
+    | { kind: 'missing' }
+    | {
+        kind: 'resolved';
+        path: NodePath<t.ArrowFunctionExpression | t.FunctionExpression | t.FunctionDeclaration>;
+      }
+    | { kind: 'unresolved' };
+
-  const getRenderPath = (object: NodePath<t.ObjectProperty>[]) => {
+  const getRenderPath = (object: NodePath<t.ObjectProperty>[]): RenderResolution => {
     const renderPath = object.find((p) => keyOf(p.node) === 'render')?.get('value');

-    if (!renderPath) {
-      return undefined;
-    }
+    if (!renderPath) return { kind: 'missing' };

     // If render is an identifier (e.g. `render: Template`), try to resolve it
     if (renderPath.isIdentifier()) {
       const resolved = resolveIdentifierInit(storyDeclaration, renderPath);
       if (
         resolved &&
         (resolved.isArrowFunctionExpression() ||
           resolved.isFunctionExpression() ||
           resolved.isFunctionDeclaration())
       ) {
-        return resolved;
+        return { kind: 'resolved', path: resolved };
       }
       // Could not resolve to a function — skip render extraction, fall through to no-function path
-      return undefined;
+      return { kind: 'unresolved' };
     }

     if (!(renderPath.isArrowFunctionExpression() || renderPath.isFunctionExpression())) {
       throw renderPath.buildCodeFrameError(
         'Expected render to be an arrow function or function expression'
       );
     }

-    return renderPath;
+    return { kind: 'resolved', path: renderPath };
   };

-  const metaRenderPath = getRenderPath(metaProps);
-  const renderPath = getRenderPath(storyProps);
-
-  storyFn ??= renderPath ?? metaRenderPath;
+  const metaRender = getRenderPath(metaProps);
+  const storyRender = getRenderPath(storyProps);
+
+  if (!storyFn) {
+    storyFn =
+      storyRender.kind === 'resolved'
+        ? storyRender.path
+        : storyRender.kind === 'missing' && metaRender.kind === 'resolved'
+          ? metaRender.path
+          : undefined;
+  }
```
</details>


Also applies to: 152-156

<details>
<summary>🤖 Prompt for AI Agents</summary>

```
Verify each finding against the current code and only fix it if needed.

In `@code/renderers/react/src/componentManifest/generateCodeSnippet.ts` around
lines 124 - 141, The current logic in getRenderPath treats an unresolved render
identifier the same as a missing render, allowing fallback to meta.render;
change getRenderPath to be tri-state: return undefined when the story has no
render property, return a distinct sentinel (e.g., a Symbol or specific string
like "UNRESOLVED_RENDER") when a render property exists but
resolveIdentifierInit(storyDeclaration, renderPath) fails to produce a function,
and return the resolved function node when resolution succeeds. Then update the
caller that inspects getRenderPath to treat the sentinel as "story-level render
exists but is unresolved" (so do NOT fallback to meta.render and proceed with
the no-function/story-level-precedence path) while still falling back to
meta.render only when getRenderPath returned undefined; use the symbols
renderPath, resolveIdentifierInit, storyDeclaration, getRenderPath, and
meta.render to locate and apply the changes.
```

</details>

